/// Parameters of Api::sendSticker(); fields mirror the official
/// documentation order, so designated initializers read like the docs.
/// @see https://core.telegram.org/bots/api#sendsticker
struct SendStickerParams {
    /// Unique identifier of the business connection on behalf of which the message will be sent
    std::optional<std::string> business_connection_id{};
    /// Unique identifier for the target chat or username of the target bot, supergroup or channel
    /// in the format \@username
    ChatId chat_id{};
    /// Unique identifier for the target message thread (topic) of a forum; for forum supergroups
    /// and private chats of bots with forum topic mode enabled only
    std::optional<std::int64_t> message_thread_id{};
    /// Identifier of the direct messages topic to which the message will be sent; required if the
    /// message is sent to a direct messages chat
    std::optional<std::int64_t> direct_messages_topic_id{};
    /// For outgoing ephemeral messages, unique identifier of the user who will receive the message;
    /// for group and supergroup chats only. It is not guaranteed that the user will receive the
    /// message, especially if they are offline. See ephemeral message sending for more details.
    std::optional<std::int64_t> receiver_user_id{};
    /// For outgoing ephemeral messages, identifier of the callback query which triggered the
    /// message if any
    std::optional<std::string> callback_query_id{};
    // clang-format off
    /// Sticker to send. Pass a file_id as String to send a file that exists on the Telegram servers
    /// (recommended), pass an HTTP URL as a String for Telegram to get a .WEBP sticker from the
    /// Internet, or upload a new .WEBP, .TGS, or .WEBM sticker using multipart/form-data. More
    /// information on Sending Files ». Video and animated stickers can't be sent via an HTTP URL.
    // clang-format on
    InputFile sticker{};
    /// Emoji associated with the sticker; only for just uploaded stickers
    std::optional<std::string> emoji{};
    /// Sends the message silently. Users will receive a notification with no sound.
    std::optional<bool> disable_notification{};
    /// Protects the contents of the sent message from forwarding and saving
    std::optional<bool> protect_content{};
    /// Pass True to allow up to 1000 messages per second, ignoring broadcasting limits for a fee of
    /// 0.1 Telegram Stars per message. The relevant Stars will be withdrawn from the bot's balance.
    std::optional<bool> allow_paid_broadcast{};
    /// Unique identifier of the message effect to be added to the message; for private chats only
    std::optional<std::string> message_effect_id{};
    /// A JSON-serialized object containing the parameters of the suggested post to send; for direct
    /// messages chats only. If the message is sent as a reply to another suggested post, then that
    /// suggested post is automatically declined.
    std::optional<SuggestedPostParameters> suggested_post_parameters{};
    /// Description of the message to reply to
    std::optional<ReplyParameters> reply_parameters{};
    /// Additional interface options. A JSON-serialized object for an inline keyboard, custom reply
    /// keyboard, instructions to remove a reply keyboard or to force a reply from the user.
    std::optional<ReplyMarkup> reply_markup{};
};

